INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass eine geordnete Abfolge in einer Datenbank immer numerisch sein muss?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch alphanumerisch sein"}, {"text": "Ja", "correct": false, "because": "Nicht auf Zahlen beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches SQL-Objekt erzeugt fortlaufende Werte?', 3, '[{"text": "SEQUENCE", "correct": true, "because": "Generiert eindeutige IDs"}, {"text": "TRIGGER", "correct": false, "because": "Führt Aktionen aus"}, {"text": "INDEX", "correct": false, "because": "Optimiert Abfragen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für eine geordnete Abfolge in Algorithmen wichtig?', 5, '[{"text": "Eindeutigkeit", "correct": true, "because": "Verhindert Duplikate"}, {"text": "Reihenfolge", "correct": true, "because": "Sichert Logik"}, {"text": "Skalierbarkeit", "correct": true, "because": "Unterstützt Wachstum"}, {"text": "Farbcodierung", "correct": false, "because": "Kein technischer Faktor"}, {"text": "Bildschirmgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Sequenz in SQL garantiert lückenlose Werte. b) Sie wird automatisch erstellt.', 3, '[{"text": "Beides falsch", "correct": true, "because": "a) ist falsch, Lücken möglich; b) ist falsch, muss definiert werden"}, {"text": "Nur a) stimmt", "correct": false, "because": "Lücken können auftreten"}, {"text": "Nur b) stimmt", "correct": false, "because": "Manuelle Erstellung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "Beide falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Definition einer geordneten Abfolge?', 4, '[{"text": "Startwert", "correct": false, "because": "Bestimmt Beginn"}, {"text": "Inkrement", "correct": false, "because": "Definiert Schrittweite"}, {"text": "Farbschema", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Sequenz in einer Datenbank immer aufsteigend ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch absteigend sein"}, {"text": "Ja", "correct": false, "because": "Richtung konfigurierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche SQL-Befehle steuern eine geordnete Abfolge?', 4, '[{"text": "CREATE SEQUENCE", "correct": true, "because": "Erstellt Sequenz"}, {"text": "NEXTVAL", "correct": true, "because": "Ruft nächsten Wert"}, {"text": "SELECT", "correct": false, "because": "Für Abfragen"}, {"text": "INSERT", "correct": false, "because": "Fügt Daten ein"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Sequenzen nur für Primärschlüssel genutzt werden. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch für andere eindeutige Werte"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Sequenz in einem Algorithmus immer linear?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch nicht-linear sein"}, {"text": "Ja", "correct": false, "because": "Struktur variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen eine Sequenz in SQL nützlich?', 5, '[{"text": "Automatische Generierung", "correct": true, "because": "Vereinfacht ID-Vergabe"}, {"text": "Eindeutigkeit", "correct": true, "because": "Verhindert Konflikte"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Kein Sequenzfaktor"}, {"text": "Farbliche Darstellung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Erstellung einer Sequenz?', 4, '[{"text": "Startwert und Inkrement", "correct": true, "because": "Definieren Verhalten"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sequenzen können zyklisch sein. b) Sie sind immer lückenlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Lücken möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Sequenz in SQL?', 3, '[{"text": "Startwert", "correct": false, "because": "Bestimmt Beginn"}, {"text": "Inkrement", "correct": false, "because": "Definiert Schritt"}, {"text": "Farbanpassung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich eine Sequenz in SQL erstelle?', 4, '[{"text": "Mit CREATE SEQUENCE", "correct": true, "because": "Definiert Sequenz"}, {"text": "Mit SELECT", "correct": false, "because": "Für Abfragen"}, {"text": "Mit UPDATE", "correct": false, "because": "Ändert Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Sequenzen immer global eindeutig sind. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Innerhalb der Datenbank eindeutig"}, {"text": "Nein", "correct": false, "because": "Garantieren Eindeutigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, eine Sequenz effizient zu nutzen?', 4, '[{"text": "Caching", "correct": true, "because": "Reduziert Zugriffe"}, {"text": "Manuelle Vergabe", "correct": false, "because": "Fehleranfällig"}, {"text": "Zufällige Werte", "correct": false, "because": "Unzuverlässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss eine Sequenz immer fortlaufend sein?', 2, '[{"text": "Nein", "correct": true, "because": "Lücken sind möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Sequenz in einer Datenbank?', 5, '[{"text": "Automatisierung", "correct": true, "because": "Vereinfacht ID-Vergabe"}, {"text": "Eindeutigkeit", "correct": true, "because": "Verhindert Konflikte"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Kein Vorteil"}, {"text": "Visuelle Darstellung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung einer Sequenz unwichtig?', 3, '[{"text": "Inkrement", "correct": false, "because": "Bestimmt Schrittweite"}, {"text": "Startwert", "correct": false, "because": "Setzt Beginn"}, {"text": "Sequenzfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich eine Sequenz für IDs brauche?', 4, '[{"text": "CREATE SEQUENCE und NEXTVAL nutzen", "correct": true, "because": "Erstellt und ruft Werte"}, {"text": "Manuell Werte setzen", "correct": false, "because": "Fehleranfällig"}, {"text": "Zufällig wählen", "correct": false, "because": "Unzuverlässig"}]');
